def _count_fresh_nonempty_paths(paths: list[Path], freshness_floor: float) -> int:
    seen: set[str] = set()
    count = 0
    for path in paths:
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        try:
            stat = path.stat()
        except OSError:
            continue
        if stat.st_size <= 0 or stat.st_mtime < freshness_floor:
            continue
        count += 1
    return count


